use super::*;

/// A basic connectable ADV observation (public address, no services) — mutate fields per test.
fn adv(addr: &str, rssi: i32, ts_ms: i64) -> Observation {
    Observation {
        addr: addr.into(),
        addr_type: "public".into(),
        rssi,
        name: None,
        company_id: None,
        services: vec![],
        tx_power: None,
        connectable: true,
        scan_req: false,
        ts_ms,
    }
}

fn kinds(f: &[Finding]) -> Vec<&str> {
    f.iter().map(|x| x.kind.as_str()).collect()
}

#[test]
fn build_profiles_learns_rssi_cadence_and_identity_per_device() {
    let obs: Vec<Observation> = (0..10)
        .map(|i| {
            let mut o = adv("AA", -50 + (i % 3) - 1, i as i64 * 100);
            o.services = vec!["180f".into()];
            o.company_id = Some(0x004C);
            o
        })
        .collect();
    let p = build_profiles(&obs);
    let a = &p["AA"];
    assert_eq!(a.count, 10);
    assert!((a.interval_mean_ms - 100.0).abs() < 1.0, "cadence learned");
    assert!(a.rssi_std > 0.0, "rssi spread learned");
    assert!(a.services.contains("180f") && a.company_ids.contains(&0x004C));
}

#[test]
fn address_twin_fires_on_concurrent_clusters_but_not_on_movement() {
    let t = Thresholds::default();
    // A clone: strong (-40) and weak (-72) samples INTERLEAVED in time — two transmitters at once.
    let mut clone = Vec::new();
    for i in 0..5 {
        clone.push(adv("AA", -40, i * 10));
        clone.push(adv("AA", -72, i * 10 + 5));
    }
    assert_eq!(kinds(&address_twin(&clone, &t)), vec!["address-twin"]);

    // Movement: the same 30 dB spread, but the two levels are DISJOINT in time — one device walking off.
    let mut moving = Vec::new();
    for i in 0..5 {
        moving.push(adv("BB", -40, i * 10));
    }
    for i in 0..5 {
        moving.push(adv("BB", -72, 1000 + i * 10));
    }
    assert!(address_twin(&moving, &t).is_empty(), "sequential drift is not a twin");
}

#[test]
fn rssi_deviation_flags_a_known_device_at_the_wrong_footprint() {
    let t = Thresholds::default();
    let base_obs: Vec<Observation> = (0..12).map(|i| adv("AA", -50 + (i % 3) - 1, i as i64 * 100)).collect();
    let base = build_profiles(&base_obs);
    // A live packet claiming to be AA but arriving 40 dB weaker — a spoofer transmitting from elsewhere.
    let live = vec![adv("AA", -90, 999999)];
    assert_eq!(kinds(&rssi_deviation(&live, &base, &t)), vec!["rssi-deviation"]);
    // A live packet within the normal footprint says nothing.
    assert!(rssi_deviation(&[adv("AA", -50, 999999)], &base, &t).is_empty());
}

#[test]
fn interval_anomaly_flags_the_wrong_cadence() {
    let t = Thresholds::default();
    let base = build_profiles(&(0..12).map(|i| adv("AA", -50, i as i64 * 100)).collect::<Vec<_>>());
    // Live AA advertising 5x slower than its baseline.
    let live: Vec<Observation> = (0..4).map(|i| adv("AA", -50, i as i64 * 500)).collect();
    assert_eq!(kinds(&interval_anomaly(&live, &base, &t)), vec!["interval-anomaly"]);
}

#[test]
fn service_mismatch_flags_an_imperfect_clone() {
    let t = Thresholds::default();
    let mut base_obs = Vec::new();
    for i in 0..10 {
        let mut o = adv("AA", -50, i * 100);
        o.services = vec!["180f".into()];
        base_obs.push(o);
    }
    let base = build_profiles(&base_obs);
    // A packet on AA advertising a service AA never had.
    let mut spoof = adv("AA", -50, 999999);
    spoof.services = vec!["fff0".into()];
    assert_eq!(kinds(&service_mismatch(&[spoof], &base, &t)), vec!["service-mismatch"]);
}

#[test]
fn tracker_non_rotation_flags_a_static_random_address_only() {
    let t = Thresholds::default();
    // A random address unbroken across 25 minutes.
    let tracker: Vec<Observation> = (0..10)
        .map(|i| {
            let mut o = adv("RR", -60, i as i64 * (25 * 60_000 / 9));
            o.addr_type = "random".into();
            o
        })
        .collect();
    assert_eq!(kinds(&tracker_non_rotation(&tracker, &t)), vec!["tracker-non-rotation"]);
    // The same span on a PUBLIC address is normal (public addresses do not rotate by design).
    let public: Vec<Observation> = (0..10).map(|i| adv("PP", -60, i as i64 * (25 * 60_000 / 9))).collect();
    assert!(tracker_non_rotation(&public, &t).is_empty());
}

#[test]
fn rogue_scan_flags_a_scan_request_flood() {
    let t = Thresholds::default();
    // 40 scan requests from one source inside one minute.
    let flood: Vec<Observation> = (0..40)
        .map(|i| {
            let mut o = adv("SC", -55, i as i64 * 1500);
            o.scan_req = true;
            o
        })
        .collect();
    assert_eq!(kinds(&rogue_scan(&flood, &t)), vec!["rogue-scan"]);
}

#[test]
fn analyze_is_quiet_on_normal_and_orders_by_severity() {
    let t = Thresholds::default();
    let normal: Vec<Observation> = (0..12).map(|i| adv("AA", -50 + (i % 3) - 1, i as i64 * 100)).collect();
    assert!(analyze(&normal, None, &t).is_empty(), "a clean capture yields nothing");

    // A capture with both a high (twin) and a medium (rogue-scan) finding — high must sort first.
    let mut mixed = Vec::new();
    for i in 0..5 {
        mixed.push(adv("AA", -40, i * 10));
        mixed.push(adv("AA", -72, i * 10 + 5));
    }
    for i in 0..40 {
        let mut o = adv("SC", -55, i as i64 * 1500);
        o.scan_req = true;
        mixed.push(o);
    }
    let f = analyze(&mixed, None, &t);
    assert_eq!(f.first().unwrap().severity, "high", "most-severe first");
    assert!(kinds(&f).contains(&"address-twin") && kinds(&f).contains(&"rogue-scan"));
}

#[test]
fn a_baseline_round_trips_through_json() {
    let base = build_profiles(&(0..10).map(|i| adv("AA", -50, i as i64 * 100)).collect::<Vec<_>>());
    let s = serde_json::to_string(&base).unwrap();
    let back: std::collections::BTreeMap<String, DeviceProfile> = serde_json::from_str(&s).unwrap();
    assert_eq!(base, back, "profiles survive save/load (the analyze --baseline path)");
}
